// SessionCookie is the name of the HttpOnly, SameSite=Lax cookie that
// carries a login.
const SessionCookie = "session"

// sessionKey is what the request context keys the logged-in user by.
type sessionKey struct{}

// UserFrom reports the user the request's session cookie names, as the
// session middleware put it on the request. Handlers of the API under
// /api/ call it; an anonymous request has neither.
func UserFrom(ctx context.Context) (*store.User, bool) {
	u, ok := ctx.Value(sessionKey{}).(*store.User)
	return u, ok
}

// session authenticates a request from its session cookie: it reads the
// cookie, asks the store for the session and the user, and puts the user
// on the request. A request without the cookie, or with one the store does
// not know, reaches next unnamed; the handler answers 401 when it needs a
// user. The cookie path is "/", so the browser sends it to every path.
func (s *Server) session(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		c, err := r.Cookie(SessionCookie)
		if err != nil || c.Value == "" {
			next.ServeHTTP(w, r)
			return
		}
		sess, err := s.store.GetSession(r.Context(), c.Value)
		if err != nil {
			if !errors.Is(err, store.ErrNotFound) {
				logError(r.Context(), "session", err)
			}
			next.ServeHTTP(w, r)
			return
		}
		user, err := s.store.GetUserByID(r.Context(), sess.UserID)
		if err != nil {
			if !errors.Is(err, store.ErrNotFound) {
				logError(r.Context(), "session user", err)
			}
			next.ServeHTTP(w, r)
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), sessionKey{}, user)))
	})
}

// requireUser is the guard of a handler that only a logged-in user may
// reach: it answers 401 to an anonymous request and calls next with the
// user on the request's context. The feature cards wrap their handlers in
// it, so a session cookie is what names the caller everywhere under /api/.
func (s *Server) requireUser(next func(http.ResponseWriter, *http.Request, *store.User)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user, ok := UserFrom(r.Context())
		if !ok {
			writeError(w, http.StatusUnauthorized, "login required")
			return
		}
		next(w, r, user)
	}
}

// newSessionCookie returns a random cookie value: 32 bytes, URL-safe base
// 64 without padding.
func newSessionCookie() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b[:]), nil
}

// setSessionCookie puts the login cookie on the response, valid until
// expiresAt. The session is HttpOnly, so no script reads it; SameSite=Lax,
// so it travels on a top-level GET (the redirect of /<slug>) but not on
// another site's POST; path "/", so it reaches the API and the app alike;
// and Secure always, because the service is served over https and a session
// must never cross an insecure connection.
func setSessionCookie(w http.ResponseWriter, value string, expiresAt time.Time) {
	http.SetCookie(w, &http.Cookie{
		Name:     SessionCookie,
		Value:    value,
		Path:     "/",
		Expires:  expiresAt.UTC(),
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
	})
}

// clearSessionCookie drops the login cookie from the browser, with the same
// attributes so the browser matches the one it holds.
func clearSessionCookie(w http.ResponseWriter) {
	http.SetCookie(w, &http.Cookie{
		Name:     SessionCookie,
		Value:    "",
		Path:     "/",
		MaxAge:   -1,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
	})
}

// logError records a failure the handler cannot answer to the client. Its
// message names only the app's own fault: never a cookie, an email or a
// password, which must not land in the logs.
func logError(_ context.Context, what string, err error) {
	log.Printf("server: %s: %v", what, err)
}
