// TestHealthz is the card's acceptance item: GET /healthz returns 200 with
// status ok.
func TestHealthz(t *testing.T) {
	srv := httptest.NewServer(server.New(server.Config{DataDir: t.TempDir()}))
	defer srv.Close()

	res, err := http.Get(srv.URL + "/healthz")
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = res.Body.Close() }()
	body, err := io.ReadAll(res.Body)
	if err != nil {
		t.Fatal(err)
	}
	if res.StatusCode != http.StatusOK {
		t.Fatalf("GET /healthz: status %d, want 200", res.StatusCode)
	}
	var got map[string]string
	if err := json.Unmarshal(body, &got); err != nil {
		t.Fatalf("GET /healthz: body %q is not JSON: %v", body, err)
	}
	if got["status"] != "ok" {
		t.Errorf("GET /healthz: body %s, want status ok", body)
	}
}

// The end-to-end test of the foundation: POST /api/signup creates a user in
// the store and GET /healthz still answers ok, so the wiring of store,
// middleware and routes runs over one handler.
func TestSignupThenHealthz(t *testing.T) {
	dir := t.TempDir()
	srv := httptest.NewServer(server.New(server.Config{DataDir: dir}))
	defer srv.Close()

	res, err := srv.Client().Post(srv.URL+"/api/signup", "application/json",
		strings.NewReader(`{"email":"sebastian@example.com","password":"hunter2hunter2"}`))
	if err != nil {
		t.Fatal(err)
	}
	body, _ := io.ReadAll(res.Body)
	_ = res.Body.Close()
	if res.StatusCode != http.StatusCreated {
		t.Fatalf("POST /api/signup: status %d body %s, want 201", res.StatusCode, body)
	}
	var created map[string]any
	if err := json.Unmarshal(body, &created); err != nil {
		t.Fatalf("POST /api/signup: body %q is not JSON: %v", body, err)
	}
	if created["email"] != "sebastian@example.com" {
		t.Errorf("POST /api/signup: body %s, want the created email named", body)
	}

	headres, err := http.Get(srv.URL + "/healthz")
	if err != nil {
		t.Fatal(err)
	}
	hbody, _ := io.ReadAll(headres.Body)
	_ = headres.Body.Close()
	if headres.StatusCode != http.StatusOK || !strings.Contains(string(hbody), `"status":"ok"`) {
		t.Errorf("GET /healthz after signup: %d %q, want 200 with status ok", headres.StatusCode, hbody)
	}

	// The same file again: the account really went to $DATA_DIR/links.db.
	again, err := srv.Client().Post(srv.URL+"/api/signup", "application/json",
		strings.NewReader(`{"email":"sebastian@example.com","password":"hunter2hunter2"}`))
	if err != nil {
		t.Fatal(err)
	}
	_ = again.Body.Close()
	if again.StatusCode != http.StatusConflict {
		t.Errorf("POST /api/signup twice: status %d, want 409 for the email taken", again.StatusCode)
	}
}

